const listAccessTokensByUserID = `-- name: ListAccessTokensByUserID :many
SELECT id, user_id, name, token_hash, token_last_eight, scopes, expires_at, last_used_at, created_at, updated_at, system_issued
FROM access_tokens
WHERE user_id = $1
ORDER BY created_at DESC
`

func (q *Queries) ListAccessTokensByUserID(ctx context.Context, userID int64) ([]AccessToken, error) {
	rows, err := q.db.Query(ctx, listAccessTokensByUserID, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AccessToken{}
	for rows.Next() {
		var i AccessToken
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.Name,
			&i.TokenHash,
			&i.TokenLastEight,
			&i.Scopes,
			&i.ExpiresAt,
			&i.LastUsedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.SystemIssued,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

