const rotateOAuthAccountTokensByAccessCAS = `-- name: RotateOAuthAccountTokensByAccessCAS :execrows
UPDATE oauth_accounts
SET access_token_encrypted = $1,
    refresh_token_encrypted = $2,
    expires_at = $3,
    updated_at = NOW()
WHERE provider = $4
  AND provider_user_id = $5
  AND access_token_encrypted IS NOT DISTINCT FROM $6
`

type RotateOAuthAccountTokensByAccessCASParams struct {
	AccessTokenEncrypted    []byte             `json:"access_token_encrypted"`
	RefreshTokenEncrypted   []byte             `json:"refresh_token_encrypted"`
	ExpiresAt               pgtype.Timestamptz `json:"expires_at"`
	Provider                string             `json:"provider"`
	ProviderUserID          string             `json:"provider_user_id"`
	OldAccessTokenEncrypted []byte             `json:"old_access_token_encrypted"`
}

// RotateOAuthAccountTokensByAccessCAS is the RACE-HEALING rotation. It keys ONLY
// on the old access-token ciphertext, deliberately ignoring the refresh column.
//
// Why it exists: GitHub App refresh tokens are single-use. When two API replicas
// refresh the same account concurrently, one wins and one gets bad_refresh_token.
// The loser's ClearOAuthAccountRefreshTokenCAS can land BEFORE the winner's
// RotateOAuthAccountTokensCAS, NULLing refresh_token_encrypted — which makes the
// winner's refresh-keyed CAS match zero rows and silently discard the freshly
// minted, still-valid refresh token. The account is then permanently stuck in
// "reconnect" despite a healthy grant. The winner holds the newest credential by
// construction, so it re-asserts over a concurrently-cleared refresh column.
func (q *Queries) RotateOAuthAccountTokensByAccessCAS(ctx context.Context, arg RotateOAuthAccountTokensByAccessCASParams) (int64, error) {
	result, err := q.db.Exec(ctx, rotateOAuthAccountTokensByAccessCAS,
		arg.AccessTokenEncrypted,
		arg.RefreshTokenEncrypted,
		arg.ExpiresAt,
		arg.Provider,
		arg.ProviderUserID,
		arg.OldAccessTokenEncrypted,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const rotateOAuthAccountTokensCAS = `-- name: RotateOAuthAccountTokensCAS :execrows
UPDATE oauth_accounts
SET access_token_encrypted = $1,
    refresh_token_encrypted = $2,
    expires_at = $3,
    updated_at = NOW()
WHERE provider = $4
  AND provider_user_id = $5
  AND access_token_encrypted IS NOT DISTINCT FROM $6
  AND refresh_token_encrypted IS NOT DISTINCT FROM $7
`

type RotateOAuthAccountTokensCASParams struct {
	AccessTokenEncrypted     []byte             `json:"access_token_encrypted"`
	RefreshTokenEncrypted    []byte             `json:"refresh_token_encrypted"`
	ExpiresAt                pgtype.Timestamptz `json:"expires_at"`
	Provider                 string             `json:"provider"`
	ProviderUserID           string             `json:"provider_user_id"`
	OldAccessTokenEncrypted  []byte             `json:"old_access_token_encrypted"`
	OldRefreshTokenEncrypted []byte             `json:"old_refresh_token_encrypted"`
}

func (q *Queries) RotateOAuthAccountTokensCAS(ctx context.Context, arg RotateOAuthAccountTokensCASParams) (int64, error) {
	result, err := q.db.Exec(ctx, rotateOAuthAccountTokensCAS,
		arg.AccessTokenEncrypted,
		arg.RefreshTokenEncrypted,
		arg.ExpiresAt,
		arg.Provider,
		arg.ProviderUserID,
		arg.OldAccessTokenEncrypted,
		arg.OldRefreshTokenEncrypted,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateAccessTokenLastUsed = `-- name: UpdateAccessTokenLastUsed :exec
UPDATE access_tokens
SET last_used_at = NOW(),
    updated_at = NOW()
WHERE id = $1
  AND (last_used_at IS NULL OR last_used_at < NOW() - INTERVAL '5 minutes')
`

// Throttled to one write per five minutes per token: agents poll with their
// tokens, and an unthrottled stamp rewrote the row on every request.
func (q *Queries) UpdateAccessTokenLastUsed(ctx context.Context, id int64) error {
	_, err := q.db.Exec(ctx, updateAccessTokenLastUsed, id)
	return err
}

