const upsertEmailAddress = `-- name: UpsertEmailAddress :one
WITH unset_primary AS (
    UPDATE email_addresses AS ea
    SET is_primary = FALSE,
        updated_at = NOW()
	    WHERE ea.user_id = $1
	      AND ea.is_primary = TRUE
	      AND ea.lower_email <> $4
	      AND $2::boolean = TRUE
	    RETURNING ea.id
),
upserted AS (
    INSERT INTO email_addresses (user_id, email, lower_email, is_activated, is_primary)
    SELECT
        $1,
        $3,
        $4,
        $5,
        $2::boolean
    FROM (SELECT 1) AS force_cte
    LEFT JOIN unset_primary ON TRUE
    ON CONFLICT (user_id, lower_email)
    DO UPDATE SET
        email = EXCLUDED.email,
        is_activated = EXCLUDED.is_activated,
        is_primary = EXCLUDED.is_primary,
        updated_at = NOW()
    RETURNING id, user_id, email, lower_email, is_activated, is_primary, created_at, updated_at
)
SELECT id, user_id, email, lower_email, is_activated, is_primary, created_at, updated_at FROM upserted
`

type UpsertEmailAddressParams struct {
	UserID      int64  `json:"user_id"`
	IsPrimary   bool   `json:"is_primary"`
	Email       string `json:"email"`
	LowerEmail  string `json:"lower_email"`
	IsActivated bool   `json:"is_activated"`
}

type UpsertEmailAddressRow struct {
	ID          int64     `json:"id"`
	UserID      int64     `json:"user_id"`
	Email       string    `json:"email"`
	LowerEmail  string    `json:"lower_email"`
	IsActivated bool      `json:"is_activated"`
	IsPrimary   bool      `json:"is_primary"`
	CreatedAt   time.Time `json:"created_at"`
	UpdatedAt   time.Time `json:"updated_at"`
}

func (q *Queries) UpsertEmailAddress(ctx context.Context, arg UpsertEmailAddressParams) (UpsertEmailAddressRow, error) {
	row := q.db.QueryRow(ctx, upsertEmailAddress,
		arg.UserID,
		arg.IsPrimary,
		arg.Email,
		arg.LowerEmail,
		arg.IsActivated,
	)
	var i UpsertEmailAddressRow
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.Email,
		&i.LowerEmail,
		&i.IsActivated,
		&i.IsPrimary,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

